#!/usr/bin/env bash
# Doc : nouvelle partie 3 « Docker : en local et sur le serveur » — Pourquoi Docker, L'infrastructure locale,
# L'image Docker (déplacée depuis Infrastructure, avec ce que next.config.ts prépare pour elle),
# Une infrastructure de serveur (modèle générique). Composant <Infra> (schémas). Parties renumérotées.
# Pas de migration. Prérequis : apply-docs-package-json.sh.
# Usage (racine du repo) : bash apply-docs-partie-docker.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/docker/pourquoi-docker.mdx" 2>/dev/null | grep -qF "## Les mots de Docker"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "## Les autres paquets, un par un" "apps/web/content/docs/dev/configuration/package-json-et-monorepo.mdx" 2>/dev/null || { echo "lancez d'abord apply-docs-package-json.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/configuration/next-config.mdx" "apps/web/content/docs/dev/configuration/typescript-et-tsconfig.mdx" "apps/web/content/docs/dev/configuration/variables-d-environnement.mdx" "apps/web/content/docs/dev/demarrer/facon-de-travailler.mdx" "apps/web/content/docs/dev/demarrer/les-outils.mdx" "apps/web/content/docs/dev/envois/les-photos-d-iphone.mdx" "apps/web/content/docs/dev/index.mdx" "apps/web/content/docs/dev/infrastructure/la-sandbox.mdx" "apps/web/content/docs/dev/infrastructure/mettre-en-production.mdx" "apps/web/content/docs/dev/qualite/la-chaine-pnpm-check.mdx" "apps/web/src/features/docs/glossary/glossary.dev.json" "apps/web/src/features/docs/glossary/remarkGlossary.ts" "apps/web/src/features/docs/lib/docs.navigation.ts" "apps/web/src/mdx-components.tsx" "e2e/docs-demarrer.spec.ts" "apps/web/content/docs/dev/infrastructure/l-image-docker.mdx")
CREATED=("apps/web/content/docs/dev/docker/l-image-docker.mdx" "apps/web/content/docs/dev/docker/l-infrastructure-locale.mdx" "apps/web/content/docs/dev/docker/pourquoi-docker.mdx" "apps/web/content/docs/dev/docker/une-infrastructure-serveur.mdx" "apps/web/src/features/docs/ui/Infra.tsx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "apps/web/content/docs/dev/docker" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "## Les mots de Docker" "apps/web/content/docs/dev/docker/pourquoi-docker.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/docker"
